with p as (select id from liq_proveedores where nombre='WisdomTree')
update liq_proveedores set email_patron='MIXTO (dos formatos oficiales coexisten): {inicial_nombre}{apellido}@wisdomtree.com (ej. jzaloom@wisdomtree.com, Media Relations) y {nombre}.{apellido}@wisdomtree.com (ej. Jeremy.Campbell@wisdomtree.com, Head of Investor Relations). Ningún correo derivado es fiable sin verificación previa.', email_patron_fuente='https://secure.businesswire.com/news/home/20260716956198/en/WisdomTree-Schedules-Earnings-Conference-Call-for-Q2-on-July-31-2026-at-1100-a.m.-ET (jzaloom@wisdomtree.com, jul-2026) y https://ir.wisdomtree.com/company-information/contacts (Jeremy.Campbell@wisdomtree.com, Head of Investor Relations; mismo formato en 8-K FY2026 https://www.sec.gov/Archives/edgar/data/880631/000121465926003292/ex99_1.htm) · confianza: media',
 canales_publicos='[{"canal": "Sitio oficial (WisdomTree / unidad Digital Assets: WisdomTree Prime y WisdomTree Connect)", "valor": "https://www.wisdomtree.com", "fuente": "https://www.businesswire.com/news/home/20260716956198/en/"}, {"canal": "Página de equipo ejecutivo (IR) — no se pudo abrir en esta verificación; listado de Will Peck no reconfirmado", "valor": "https://ir.wisdomtree.com/company-information/executive-team", "fuente": "https://ir.wisdomtree.com/company-information"}, {"canal": "LinkedIn empresa", "valor": "https://www.linkedin.com/company/wisdomtree", "fuente": "https://www.linkedin.com/company/wisdomtree"}, {"canal": "Contacto de prensa / media relations (jzaloom@ verificado como publicado; nramsammy@ y fullyvested no reconfirmados en esta pasada)", "valor": "jzaloom@wisdomtree.com; nramsammy@wisdomtree.com; wisdomtree@fullyvested.com", "fuente": "https://secure.businesswire.com/news/home/20260716956198/en/WisdomTree-Schedules-Earnings-Conference-Call-for-Q2-on-July-31-2026-at-1100-a.m.-ET"}, {"canal": "Investor Relations (Jeremy Campbell, Head of Investor Relations) — buzón publicado oficialmente, útil solo para redirección", "valor": "Jeremy.Campbell@wisdomtree.com", "fuente": "https://ir.wisdomtree.com/company-information/contacts"}, {"canal": "X / Twitter", "valor": "@WisdomTreeNews", "fuente": "https://www.businesswire.com/news/home/20260716956198/en/"}, {"canal": "Plataforma institucional WisdomTree Connect (B2B/B2B2C; formulario de contacto institucional no localizado)", "valor": null, "fuente": "https://solana.com/vi/news/wisdomtree-tokenization-solana"}, {"canal": "Buzón genérico: Jessica Zaloom — Head of Corporate Communications & Public Relations / Media Relations (contacto de prensa corporativo)", "valor": "jzaloom@wisdomtree.com", "fuente": "https://secure.businesswire.com/news/home/20260716956198/en/WisdomTree-Schedules-Earnings-Conference-Call-for-Q2-on-July-31-2026-at-1100-a.m.-ET"}]'::jsonb, ruta_recomendada='1) Enviar el correo a John Whelan (Head of Strategy, Digital Assets; nombrado el 1-jun-2026 con mandato explícito de alianzas con instituciones financieras y expansión a Latinoamérica), con CC a Maredith Hannon (Business Development, Digital Assets; cargo no reconfirmado para 2025-2026). IMPORTANTE: WisdomTree usa dos formatos de correo (jzaloom@ y Jeremy.Campbell@), así que antes de enviar verificar la dirección de Whelan con una herramienta de validación o enviar InMail por LinkedIn; no disparar a ambas variantes a ciegas. Enfocar en cross-listing/distribución secundaria de los fondos tokenizados de WisdomTree Connect hacia Centroamérica vía Kabal Digital Marketplace (PSAD-0056) y en facilidad programática/anchor liquidity. 2) Si no hay respuesta en 7-10 días, escalar a Will Peck (Head of Digital Assets, decisor; confirmado en el cargo en jun-2026) referenciando el primer correo. 3) Intro cálida: DTCC Digital Assets/ex-Securrency, Stellar Development Foundation o Solana Foundation (cadenas soportadas por Connect), Circle/stablecoins, o red de Whelan en Santander CIB. 4) Fallback: escribir a media relations (jzaloom@wisdomtree.com, único buzón nominal verificado como publicado) pidiendo redirección al equipo de Digital Assets, o mensaje directo por LinkedIn a Whelan/Hannon.',
 decisor=coalesce('Will Peck — Head of Digital Assets',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'Emisor de fondos tokenizados en Ethereum y Stellar (WisdomTree Prime, WisdomTree Connect, WisdomTree Digital Funds).'||E'\n'||'Investigación automática 2026-10-19 (lote EXPLORE 2 del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 12 búsquedas. Buzones genéricos movidos a canales_publicos: Jessica Zaloom. Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='WisdomTree'), v.* from (values
('John Whelan','Head of Strategy, Digital Assets','Digital Assets (reporta a Will Peck, Head of Digital Assets)','Estados Unidos (el comunicado dice ''based in the U.S.''; ciudad no especificada)',null,'jwhelan@wisdomtree.com','patron_no_verificado','entrada',1,'Nombrado el 1-jun-2026 para liderar la estrategia de la unidad, supervisar inversiones estratégicas y trabajar con Business Development y Producto en alianzas con instituciones financieras y firmas cripto, con expansión explícita a Europa, Asia y Latinoamérica. Casi una década liderando activos digitales en Santander CIB: entiende bancos y mercados emergentes.','https://www.ledgerinsights.com/john-whelan-joins-wisdomtree-to-lead-digital-assets-strategy/','Verificación: nombramiento confirmado por cuatro fuentes independientes (Ledger Insights, 01net.it, GeneOnline, FinancialContent/BizWire 1-jun-2026: https://www.financialcontent.com/article/bizwire-2026-6-1-wisdomtree-appoints-john-whelan-as-head-of-strategy-for-digital-assets). Se corrigió la ubicación: el comunicado solo dice ''based in the U.S.'', no Nueva York. Sin evidencia pública de actividad posterior al nombramiento. Correo derivado del patrón {inicial}{apellido}; WisdomTree también usa {nombre}.{apellido} (Jeremy.Campbell@), así que la variante john.whelan@wisdomtree.com es igualmente plausible: validar antes de enviar.'),
('Will Peck','Head of Digital Assets','Digital Assets (WisdomTree Prime, WisdomTree Connect, fondos tokenizados / WisdomTree Digital Trust Company)','Nueva York, EE. UU.',null,'wpeck@wisdomtree.com','patron_no_verificado','dueno_programa',2,'Dirige la unidad de activos digitales (cripto, stablecoins y tokenización) y es el decisor final de alianzas. Confirmado en el cargo a jun-2026: el comunicado del nombramiento de Whelan indica que este ''will report to Will Peck, Head of Digital Assets at WisdomTree''.','https://www.financialcontent.com/article/bizwire-2026-6-1-wisdomtree-appoints-john-whelan-as-head-of-strategy-for-digital-assets','Verificación: cargo vigente confirmado en comunicado del 1-jun-2026 (línea de reporte de Whelan). Se cambió la fuente a un documento fechado de 2026 porque la página de equipo ejecutivo de IR (https://ir.wisdomtree.com/company-information/executive-team) no pudo abrirse en esta pasada y su listado de Peck no se reconfirmó. Perfil adicional: https://www.wisdomtree.com/us/insights/contributors/will-peck. Correo derivado, no verificado; variante alternativa will.peck@wisdomtree.com igualmente plausible (patrón corporativo mixto). Ex-board member de Securrency (hoy DTCC Digital Assets), posible vía de intro.'),
('Maredith Hannon','Director / Head of Business Development, Digital Assets (título varía según fuente; no reconfirmado para 2025-2026)','Digital Assets - Business Development & Partnerships (WisdomTree Prime / Connect)','Nueva York, EE. UU.',null,'mhannon@wisdomtree.com','patron_no_verificado','entrada',3,'Lideró desarrollo de negocio y alianzas de la división de activos digitales (desde 2022) y presentó públicamente el lanzamiento de WisdomTree Connect para institucionales. Punto de entrada natural para distribución/cross-listing si sigue en el cargo.','https://www.wisdomtree.com/us/insights/contributors/maredith-hannon','Verificación: búsqueda ''"Maredith Hannon" WisdomTree 2026'' no arrojó ninguna mención en 2025-2026 (ni salida ni permanencia); última evidencia pública fechada sigue siendo nov-2024 (Benzinga). La página de contribuidor no pudo abrirse en esta pasada (proxy), aunque el patrón de URL es el mismo que páginas oficiales confirmadas (p. ej. jason-guthrie). Confirmar en LinkedIn antes de contactar. Correo derivado, no verificado; variante maredith.hannon@wisdomtree.com igualmente plausible.'),
('Jason Guthrie','Head of Product, Digital Assets (título varía según fuente: la página oficial lo lista como Head of Digital Asset Product / Head of Digital Assets, Europe)','Digital Assets - Producto (construcción de iniciativas blockchain, Prime/Connect)','Londres / Nueva York (por confirmar)',null,'jguthrie@wisdomtree.com','patron_no_verificado','influencer',4,'Responsable del producto de tokenización y de las iniciativas blockchain (plataforma de tokenización, WisdomTree Prime); voz técnica que evaluaría la integración de Kabal Digital Marketplace con WisdomTree Connect (cadenas, custodia, conversión de stablecoins).','https://wisdomtree.com/us/insights/contributors/jason-guthrie','Verificación: se cambió la fuente al perfil oficial de contribuidor de WisdomTree (confirmado en resultados de búsqueda); perfiles de terceros adicionales: https://www.whaletales.thetie.io/jason-guthrie y https://blockworks.co/speaker/jason-guthrie. Ninguna fuente está fechada en 2025-2026 y los títulos difieren entre sí, así que el cargo actual NO está confirmado; verificar en LinkedIn antes de contactar. Correo derivado, no verificado; variante jason.guthrie@wisdomtree.com igualmente plausible.')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
